INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zoo Keeper', 'You control Zeke the zookeeper who must rescue his girlfriend Zelda from the Zoo. There are four levels or "adventures". Each level has its own task such as trapping the animals in the zoo, jumping ledges up the screen and jumping animals to earn a bonus keeper.' FROM games WHERE igdb_id = 23872 ON CONFLICT (game_id, language_code) DO NOTHING;
