INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Deathchase', 'Deathchase is a 1983 computer game written for the ZX Spectrum by Mervyn Estcourt and published by Micromega in the UK and Ventamatic in Spain. It is commonly known by the incorrect name of "3D Deathchase", perhaps due to the prominent "3D" on the inlay, and that some magazines incorrectly referred to this title. 
