INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mappy', 'The player guides Mappy the police mouse through the mansion of the cats called Mewkies (Meowky in the U.S. version) to retrieve stolen goods. The player uses a left-right joystick to move Mappy and a single button to operate doors. The mansion has six floors of hallways in which the stolen items are stashed.' FROM games WHERE igdb_id = 2710 ON CONFLICT (game_id, language_code) DO NOTHING;
