INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong II', 'Donkey Kong II was developed by Nintendo R&D1 and released as part of the Game & Watch Multi Screen series, featuring two LCD screens. It was released in 1983. Donkey Kong Jr. has to touch a key, then it moves up to the top screen. Donkey Kong Jr. has to climb to the top screen while avoiding things such as electrical wires. When he gets to the top screen, Donkey Kong Jr. will have to touch the key again, and it will move to the keyhole of one of the chains. Donkey Kong Jr has to climb up the rope below the keyhole, while avoiding birds. When he gets to the top of the rope, one of the chains will unlock. He has to do this 4 times until he saves Donkey Kong. After that, the game will start over, at a somewhat faster pace.' FROM games WHERE igdb_id = 112423 ON CONFLICT (game_id, language_code) DO NOTHING;
