INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Widow', 'Black Widow is a vector arcade game developed by Atari released in 1982. The player takes the role of a Black widow spider defending a web from invading bugs. The player must move the spider around the web while simultaneously shooting/avoiding various bugs and collecting the bonuses that appear after the enemies are eliminated. The spider is controlled through two joysticks: the left one is used to move the spider, and the right one to control the shot direction.' FROM games WHERE igdb_id = 18455 ON CONFLICT (game_id, language_code) DO NOTHING;
