INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac & Pal', 'Pac & Pal is an arcade game that was released by Namco on July 30, 1983 exclusively in Japan. It runs on Namco Super Pac-Man hardware, and the object of the game is for Pac-Man to eat all the items before he is caught by the ghosts. Most of the items are fruits from the original Pac-Man game, with a few new additions. Their value varies, starting with cherries at 50 points, and ending with keys from 700 to 5000 points. The items had to first be unlocked by turning over cards distributed around the maze (instead of eating keys like in Super Pac-Man). Very few cabinets still exist today, and this is possibly one of the rarest Pac-Man titles to find in playable format outside Japan.' FROM games WHERE igdb_id = 18381 ON CONFLICT (game_id, language_code) DO NOTHING;
