INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('b-dot-c-s-quest-for-tires', 12294, '1983-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5vuq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gbhzjdu3grsqdfvels8p.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'B.C.''s Quest for Tires', 'Cute Chick is in trouble! She is being held captive by the dinosaur, and it is up to Thor to ride his trusty wheel to the rescue. There are many obstacles in the way which Thor will need to jump and duck, including rocks, trees, rivers, lava pits, cliffs, and of course Fat Broad. When you duck, the character bounces up and down, so don''t duck too soon. BC''s Quest For Tires is a side scrolling action game resembling Moon Patrol in some ways, featuring characters from the comic strip BC.' FROM games WHERE igdb_id = 12294 ON CONFLICT (game_id, language_code) DO NOTHING;
