INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'M.U.L.E.', 'M.U.L.E. is about four hopeful explorers trying to make a fortune on a virgin planet. This is done by producing various goods (Food, Energy, Smithore, Crystite). Each of these goods have their uses: if you don''t have enough food, you will have less time during your turn. If you don''t have enough energy, your output will be lower. If enough smithore isn''t produced, there will be a shortage of M.U.L.E.s. Crystite is the big earner that can make or break your game.
