INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Enchanter', 'Enchanter is a 1983 interactive fiction computer game written by Marc Blank and Dave Lebling and published by Infocom. It belongs to the fantasy genre and was the first fantasy game published by Infocom after the Zork trilogy (it was originally intended to be Zork IV). The game had a parser that understood over 700 words, making it the most advanced interactive fiction game of its time. It was Infocom''s ninth game.
