INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lode Runner', 'Lode Runner is a 1983 puzzle video game, first published by Brøderbund. It is one of the first games to include a level editor, a feature that allows players to create their own levels for the game. This feature bolstered the game''s popularity, as magazines such as Computer Gaming World held contests to see who could build the best level.' FROM games WHERE igdb_id = 4603 ON CONFLICT (game_id, language_code) DO NOTHING;
