INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jr. Pac-Man', 'The gameplay of Jr. Pac-Man is similar to that of its predecessors: The player controls the titular Jr. Pac-Man and scores points by eating all of the dots in the maze. Four ghosts roam the maze and attempt to capture him. The player can eat an energizer to turn the ghosts blue, making them vulnerable for a short time and allowing the player to eat them, sending their eyes back to their home base. When all the dots are cleared, a new maze is presented and gameplay resumes.' FROM games WHERE igdb_id = 7453 ON CONFLICT (game_id, language_code) DO NOTHING;
