INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stronghold', 'On one of your patrols in deep space you encounter an abandoned base whose self-defense mechanisms are still functional. Upon detecting your presence the base launches several drones to destroy you. After having conquered three of these attack waves a force field containing of three layers will form at the bottom auf the screen protecting a SAM crawler. Your objctive now ist to shoot a gap into the horizontally moving force field in order to eliminate the SAM crawler while still being under attack by hostile drones. As soon as you breached the force field you have to pay attention not being shot down by the SAM crawler which will exploit the fact of you destroying the force field.
