INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plaque Attack', 'Plaque Attack is a 1983 video game for the Atari 2600 that was made by Activision. Loosely based on Space Invaders, the player must prevent food from destroying teeth in a person''s mouth. Steve Cartwright, who designed the game, said that game was meant to help people develop good dental habits.' FROM games WHERE igdb_id = 18410 ON CONFLICT (game_id, language_code) DO NOTHING;
