INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Bros.', 'Mario Bros. is an arcade game published by Nintendo and developed by Shigeru Miyamoto. The platform puzzle which first introduced Luigi to the world has both single and multiplayer action with two differing game types, but with the same objective. Crabs, turtles and fighter flies must be cleared out by jumping underneath the platform they sit on, then kicking them away. Each level is cleared when a set number of coins is collected. For the two player mode, the first to collect the set amount of coins wins.' FROM games WHERE igdb_id = 3105 ON CONFLICT (game_id, language_code) DO NOTHING;
