INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chuckie Egg', 'Chuckie Egg is an action platformer featuring a turn-based multiplayer mode. As Hen-House Harry, the player must collect the twelve eggs positioned in each level, before a countdown timer reaches zero. In addition there are piles of seed which may be collected to increase points and stop the countdown timer for a while. The player starts with five lives, and an extra life is awarded every 10,000 points.' FROM games WHERE igdb_id = 10235 ON CONFLICT (game_id, language_code) DO NOTHING;
