INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digger', 'Diggger is an action game in which the player digs tunnels, attempting to collect all of the emeralds on each level without being caught by monsters. The regular ''Nobbin'' monsters are easily outwitted at first since they can''t dig tunnels for themselves. However the game becomes more difficult as the amount of dug tunnels increases, and superior ''Hobbin'' monsters begin to appear.' FROM games WHERE igdb_id = 24425 ON CONFLICT (game_id, language_code) DO NOTHING;
