INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Valhalla', 'Valhalla was a text-based (with some light graphics) ZX Spectrum and Commodore 64 adventure game published in 1983 by Legend. Set in Asgard and Midgard, the goal was to collect six mythical objects, for which you needed the help of other characters, who were taken from Norse mythology and would wander around randomly.' FROM games WHERE igdb_id = 23053 ON CONFLICT (game_id, language_code) DO NOTHING;
