INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frostbite', 'You''re an Eskimo who wants to build an igloo to live in during the cold season. To do this, you must jump from ice-block to ice-block, while avoiding wildlife such as birds and crabs. Coming with contact with any of these will cause them to push you off the block and into the deadly water. Once you have built your igloo, you must enter it to proceed to the next level. Remember, you must build it before the temperature drops to 0°. You have four lives.' FROM games WHERE igdb_id = 18695 ON CONFLICT (game_id, language_code) DO NOTHING;
