INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Falcon Patrol', 'Falcon Patrol is a two-way side-scrolling shooter. Players fly a jet across a looping area and must shoot down attacking aircraft. A small radar at the bottom of the screen shows the enemies'' position. Fuel and rockets are limited, but there are several landing platforms where the jet can be refueled and resupplied. Before the jet is able to land however, it needs to be brought to a full halt right above the platform, leaving it vulnerable to attacks. Landing platforms can also be destroyed if they are bombed or enemy planes crash into them. As the game progresses, enemies attack in increasingly large and difficult waves.' FROM games WHERE igdb_id = 24496 ON CONFLICT (game_id, language_code) DO NOTHING;
