INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Congo Bongo', 'Congo Bongo is an isometric platform arcade game released by Sega in 1983. The game has come to be seen as Sega''s answer to the highly successful Donkey Kong game that was released two years prior. The player takes the role of a red-nosed safari hunter who tries to catch an ape named "Bongo". The hunter seeks Bongo to exact revenge for an apparent practical joke in which Bongo set fire to the hunter''s tent, giving him a literal "hotfoot". The game was named by Peter W. Gorrie who was the CFO of Sega at that time.' FROM games WHERE igdb_id = 5669 ON CONFLICT (game_id, language_code) DO NOTHING;
