INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunchback', 'The game is set on a castle wall. The player must cross the screen from left to right avoiding obstacles in order to ring the bell at the far right. Obstacles include pits which must be swung over on a long rope, ramparts which must be jumped (some of which contain knights with spears) and flying fireballs and arrows (to be ducked or jumped). Eventually, after completing a number of screens, the player must rescue Esmeralda. If this final screen is completed, the game begins again at a faster speed.' FROM games WHERE igdb_id = 26118 ON CONFLICT (game_id, language_code) DO NOTHING;
