INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atic Atac', 'The game takes place within a castle in which the player must seek out the "Golden Key of ACG" through unlocking doors and avoiding enemies. It was Ultimate''s second game to require 48K of RAM; most of their previous games for the Spectrum ran on unexpanded 16K models.
