INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultima III: Exodus', 'Eons ago Lord British came unto the lands of Sosaria. Since that time it has been united under his rule as the Kingdom of Britannia and has gone through two major crises. A few years ago there were political upheavals among the city states of the kingdom. The ringleader of this political instability was Mondain, the Magician. Under his horrible rule, the people''s lives were devastated. A valiant warrior was called forth from another world by Lord British. This warrior overthrew Mondain.
